mapper.select:
SELECT SHEET.BUSINESSAFFILIATION,SHEET.AUDITDISCOVERABLE,SHEET.SHEETCODE,STAFF.REALNAME,SHEET.SHEETID,NQTYPE.AUDITTYPE AS INTERNALTYPE, ORG.ORGNAME,SHEET.HZDG,SHEET.ORGIDS,SHEET.ORGIDNAMES,SHEET.IFSBG FROM TBL_NBSJ_SHEET SHEET LEFT JOIN TBL_ORGANIZATION ORG ON ORG.ORGID = SHEET.AUDITORG LEFT JOIN TBL_STAFF STAFF ON STAFF.STAFFID = SHEET.CREATESTAFF LEFT JOIN TBL_NBSJ_QUESTION_TYPE NQTYPE ON NQTYPE.TYPEID = SHEET.INTERNALTYPE
1=1 AND SHEET.RISKLEVEL = '是' AND SHEET.STATE = 6
${sql}
AND SHEET.PROJECTID = #{tblNbsjQuestionVo.projectId}
AND BUSINESSAFFILIATION like concat(concat('%',#{tblNbsjQuestionVo.businessAffiliation}),'%')
AND STAFF.STAFFID = #{tblNbsjQuestionVo.findPeople}
AND NQTYPE.AUDITTYPE like concat(concat('%',#{tblNbsjQuestionVo.internalType}),'%')
ORDER BY SHEET.SHEETID DESC
